export const BODY: string = "\n<p>امیج اسپلٹر ایک تصویر کو کئی برابر حصوں میں کاٹتا ہے، جنہیں ٹائلز کہتے ہیں۔ ہر ٹائل اصل تصویر کا ایک حصہ ہوتی ہے، اور سب مل کر پوری تصویر بناتی ہیں۔</p>\n<p>اسپلٹ کرنا کراپ کرنے سے الگ ہے۔ کراپ حصہ ہٹاتا ہے، جبکہ اسپلٹ پوری تصویر کو ٹکڑوں میں بانٹتا ہے، اور کوئی حصہ ضائع نہیں ہوتا۔</p>\n<p>یہ رہنما گرڈ موڈ، پٹیاں، پری سیٹ، مکمل ریزولوشن، شفافیت اور عام غلطیوں کی وضاحت کرتا ہے۔ آزمانے کے لیے <a href=\"/ur/tasveer-split-karein/\">امیج اسپلٹر</a> کھولیں۔</p>\n<h2 id=\"what-is-an-image-splitter\">امیج اسپلٹر کیا ہے؟</h2>\n<p>اسپلٹر تصویر کو قطاروں اور کالموں میں کاٹ کر الگ الگ فائلیں بناتا ہے۔ تین بائی تین گرڈ نو ٹائلز بناتا ہے، جنہیں الگ الگ پوسٹ یا پرنٹ کیا جا سکتا ہے۔</p>\n<p>اسپلٹر انسٹاگرام گرڈ، بڑے پرنٹ اور گیم کے اسپرائٹ کے لیے استعمال ہوتا ہے۔ ہر ٹائل اصل ریزولوشن میں رہتی ہے، اس لیے معیار نہیں گرتا۔</p>\n<p>اسپلٹ کرنے سے پہلے اصل فائل محفوظ رکھیں، کیونکہ ٹائلز سے اصل تصویر دوبارہ بنانا مشکل ہوتا ہے۔ اصل ہی آپ کا محفوظ ذریعہ ہے۔</p>\n<h2 id=\"grid-mode\">گرڈ موڈ: N بائی M ٹائلز</h2>\n<p>گرڈ موڈ میں آپ قطاروں اور کالموں کی تعداد چنتے ہیں، جیسے 3 بائی 3 یا 2 بائی 4۔ ٹول تصویر کو برابر حصوں میں بانٹ دیتا ہے، اور ہر ٹائل ایک الگ فائل بن جاتی ہے۔</p>\n<p>گرڈ تصویر کے ابعاد سے ملنا چاہیے: مربع تصویر 3 بائی 3 میں اچھی بٹتی ہے، جبکہ چوڑی تصویر 4 بائی 2 میں بہتر بٹتی ہے۔ غلط گرڈ سے ٹائلز بہت پتلی یا بہت چوڑی بن جاتی ہیں۔</p>\n<p>گرڈ بنانے سے پہلے تصویر کے ابعاد جانچیں۔ اگر ابعاد گرڈ سے پورے تقسیم نہ ہوں تو ٹول تھوڑا تراشتا ہے، اس لیے کنارے جانچ لینا اچھا ہے۔</p>\n<h2 id=\"horizontal-strips\">افقی پٹیاں</h2>\n<p>افقی پٹیاں تصویر کو اوپر سے نیچے کئی لمبی پٹیوں میں کاٹتی ہیں۔ یہ بینر، سلائیڈر اور لمبی کہانی والی تصویروں کے لیے استعمال ہوتی ہیں۔</p>\n<p>پٹیوں کی تعداد تصویر کی اونچائی پر منحصر ہے۔ لمبی تصویر کو چار پٹیوں میں کاٹنا اچھا ہے، جبکہ چھوٹی تصویر دو پٹیوں میں کافی ہے۔</p>\n<p>افقی پٹیوں میں اہم حصہ، جیسے چہرہ، ایک ہی پٹی میں رکھیں۔ اگر چہرہ دو پٹیوں میں بٹ جائے تو دونوں پٹیاں عجیب لگیں گی۔</p>\n<h2 id=\"vertical-strips\">عمودی پٹیاں</h2>\n<p>عمودی پٹیاں تصویر کو بائیں سے دائیں کاٹتی ہیں، جس سے لمبے عمودی ٹکڑے بنتے ہیں۔ یہ پینوراما اور چوڑی تصویروں کو حصوں میں بانٹنے کے لیے اچھی ہیں۔</p>\n<p>عمودی پٹیاں کیروسل پوسٹ میں اچھی لگتی ہیں، کیونکہ صارف ایک پٹی سے دوسری پٹی تک سوائپ کرتا ہے اور تصویر آہستہ آہستہ کھلتی ہے۔</p>\n<p>عمودی پٹیوں میں بھی اہم موضوع کو ایک پٹی میں رکھنے کی کوشش کریں۔ بیچ میں بٹا ہوا موضوع دونوں پٹیوں کو کمزور کر دیتا ہے۔</p>\n<h2 id=\"split-presets\">اسپلٹ پری سیٹ</h2>\n<p>پری سیٹ تیار شدہ گرڈ ہیں، جیسے انسٹاگرام کے لیے 3 بائی 3 یا پرنٹ کے لیے 2 بائی 2۔ ایک کلک میں گرڈ تیار ہو جاتا ہے، بغیر عدد لکھے۔</p>\n<p>پری سیٹ شروعات کے لیے اچھے ہیں، مگر ہر تصویر پر ایک جیسے نہیں چلتے۔ پری سیٹ لگانے کے بعد ٹائلز دیکھیں اور ضرورت ہو تو گرڈ بدلیں۔</p>\n<p>اپنا پسندیدہ گرڈ یاد رکھیں اور ہر بار وہی استعمال کریں۔ مستقل گرڈ آپ کی فیڈ یا پرنٹ کو منظم رکھتا ہے۔</p>\n<h2 id=\"full-resolution-tiles\">مکمل ریزولوشن والی ٹائلز</h2>\n<p>ٹائلز اصل ریزولوشن میں بنتی ہیں، یعنی ہر ٹائل کے پکسلز اصل تصویر کے اس حصے کے برابر ہوتے ہیں۔ اس لیے ٹائلز دھندلی نہیں ہوتیں۔</p>\n<p>مکمل ریزولوشن کا مطلب ہے کہ ٹائلز کی فائلیں بھی بڑی ہو سکتی ہیں۔ نو ٹائلز کی کل جگہ اصل فائل سے تھوڑی زیادہ ہو سکتی ہے، کیونکہ ہر فائل کا اپنا ہیڈر ہوتا ہے۔</p>\n<p>اگر ٹائلز ویب پر ڈالنی ہوں تو انہیں الگ سے کمپریس کریں۔ اصل ریزولوشن محفوظ رکھیں، مگر فائل سائز کو منزل کے مطابق کم کریں۔</p>\n<h2 id=\"numbered-tiles-and-zip-download\">نمبر والی ٹائلز اور ZIP ڈاؤن لوڈ</h2>\n<p>ٹائلز کو نمبر دیا جاتا ہے، تاکہ ان کی ترتیب معلوم رہے۔ نمبر والی فائلیں، جیسے tile-1 سے tile-9، آپ کو بتاتی ہیں کہ کون سی ٹائل کہاں لگے گی۔</p>\n<p>سب ٹائلز ایک ZIP فائل میں ڈاؤن لوڈ ہوتی ہیں، جس سے انہیں سنبھالنا آسان ہو جاتا ہے۔ ZIP کھولنے پر سب فائلیں ترتیب سے ملتی ہیں۔</p>\n<p>ZIP سے نکالتے وقت فائلوں کے نام نہ بدلیں، ورنہ ترتیب کھو جائے گی۔ اگر نام بدلنا ہو تو نمبر برقرار رکھیں۔</p>\n<h2 id=\"input-formats\">ان پٹ فارمیٹ</h2>\n<p>اسپلٹر JPG، PNG اور WebP فائلوں کو قبول کرتا ہے۔ ہر فارمیٹ کی ٹائلز اسی فارمیٹ میں بنتی ہیں، تاکہ شفافیت یا معیار نہ بدلے۔</p>\n<p>PNG تصویر کی ٹائلز بھی PNG بنتی ہیں، جس سے شفافیت بچتی ہے۔ JPG تصویر کی ٹائلز JPG بنتی ہیں، جس سے فائلیں ہلکی رہتی ہیں۔</p>\n<p>اگر فارمیٹ بدلنا ہو تو اسپلٹ کرنے سے پہلے یا بعد میں کنورٹر استعمال کریں۔ اسپلٹ کے دوران فارمیٹ بدلنا ممکن نہیں ہوتا۔</p>\n<h2 id=\"transparency-and-sprite-sheets\">شفافیت اور اسپرائٹ شیٹ</h2>\n<p>شفاف PNG تصویر کو اسپلٹ کرنے پر ہر ٹائل کی شفافیت بچتی ہے۔ یہ گیم کے اسپرائٹ اور لوگو کے لیے بہت اہم ہے، کیونکہ شفاف حصہ سفید نہیں ہونا چاہیے۔</p>\n<p>اسپرائٹ شیٹ ایک ہی تصویر میں کئی چھوٹی تصویریں رکھتی ہے، جنہیں اسپلٹر الگ الگ ٹائلز میں کاٹ دیتا ہے۔ گیم ڈویلپر اسی طریقے سے کردار اور آئیکن نکالتے ہیں۔</p>\n<p>شفاف ٹائلز کو JPG میں نہ بدلیں، کیونکہ JPG شفافیت نہیں بچاتا۔ شفافیت چاہیے ہو تو PNG یا WebP میں رکھیں۔</p>\n<h2 id=\"splitting-for-print\">پرنٹ کے لیے اسپلٹ کرنا</h2>\n<p>بڑی تصویر کو پرنٹ کے لیے کئی صفحوں میں بانٹا جا سکتا ہے، جنہیں جوڑ کر بڑا پوسٹر بنتا ہے۔ ہر ٹائل ایک صفحے پر پرنٹ ہوتی ہے۔</p>\n<p>پرنٹ کے لیے اسپلٹ کرتے وقت ہر ٹائل کے گرد تھوڑا حاشیہ چھوڑیں، تاکہ جوڑنے پر تصویر کا حصہ نہ کٹے۔ حاشیے کے بغیر جوڑا گیا پوسٹر بیچ میں خالی لکیر دکھاتا ہے۔</p>\n<p>پرنٹ سے پہلے ایک ٹائل پرنٹ کر کے جانچیں۔ اگر وہ تیز نکلے تو باقی بھی تیز نکلیں گی، اور کاغذ ضائع نہیں ہوگا۔</p>\n<h2 id=\"splitting-screenshots\">اسکرین شاٹ اسپلٹ کرنا</h2>\n<p>لمبا اسکرین شاٹ، جیسے پوری ویب سائٹ یا چیٹ، کو حصوں میں کاٹ کر الگ الگ بھیجا جا سکتا ہے۔ ہر حصہ پڑھنے میں آسان ہوتا ہے، جبکہ پورا اسکرین شاٹ چھوٹا اور ناقابل خواندگی ہو جاتا ہے۔</p>\n<p>اسکرین شاٹ کو اس طرح کاٹیں کہ متن بیچ میں نہ بٹے۔ ہر ٹائل میں مکمل پیراگراف یا مکمل حصہ رکھیں، تاکہ پڑھنے والا الجھے نہیں۔</p>\n<p>اسکرین شاٹ کی ٹائلز PNG میں رکھیں، کیونکہ متن PNG میں تیز رہتا ہے۔ JPG میں متن دھندلا ہو جاتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی غلط گرڈ چننا ہے، جس سے ٹائلز بہت چھوٹی یا بہت پتلی بن جاتی ہیں۔ دوسری غلطی اہم موضوع کو دو ٹائلز میں بانٹ دینا ہے۔</p>\n<p>تیسری غلطی اصل فائل کھو دینا ہے۔ ٹائلز سے اصل تصویر دوبارہ بنانا بہت مشکل ہے، اس لیے اصل کو ہمیشہ الگ محفوظ رکھیں۔</p>\n<p>چوتھی غلطی ٹائلز کے نام بدل دینا ہے، جس سے ترتیب کھو جاتی ہے۔ نمبر برقرار رکھیں، تاکہ ٹائلز درست ترتیب میں لگیں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: اسپلٹ کرنے کی جانچ فہرست</h2>\n<p>اسپلٹ کرنے سے پہلے گرڈ چنیں، اہم موضوع کی جگہ دیکھیں، اور اصل فائل محفوظ رکھیں۔ اسپلٹ کے بعد ٹائلز کو نمبر سے ترتیب دیں اور ایک ٹائل کھول کر معیار جانچیں۔</p>\n<p>اگر ٹائلز انسٹاگرام کے لیے ہیں تو اپ لوڈ کی ترتیب بھی لکھ لیں۔ انسٹاگرام گرڈ کی تفصیل <a href=\"/ur/blog/tasveer-split-karein-instagram-grid/\">انسٹاگرام گرڈ کے لیے تصویریں کاٹنا</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-kaise-split-karein/\">تصویر کیسے کاٹیں</a> میں دیکھیں۔</p>\n";

